// @generated by Claude Code (Sonnet 5.5) on 2026-11-03 — renders build/icon.svg to PNG with Electron
// Run: npx electron scripts/make-icon.js
const { app, BrowserWindow } = require('electron');
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const svg = fs.readFileSync(path.join(root, 'build', 'icon.svg'), 'utf8');
const outputs = [
  [1024, path.join(root, 'build', 'icon.png')],
  [256, path.join(root, 'src', 'assets', 'icon.png')],
  [256, path.join(root, '..', 'docs', 'assets', 'icon.png')],
];

app.whenReady().then(async () => {
  const win = new BrowserWindow({ show: false, width: 1024, height: 1024, useContentSize: true, transparent: true, frame: false, webPreferences: { offscreen: true } });
  await win.loadURL('data:text/html;charset=utf-8,' + encodeURIComponent(`<!doctype html><body style="margin:0;background:transparent;overflow:hidden">${svg}</body>`));
  await new Promise((r) => setTimeout(r, 400));
  const image = await win.webContents.capturePage({ x: 0, y: 0, width: 1024, height: 1024 });
  for (const [size, file] of outputs) {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    const resized = image.getSize().width === size ? image : image.resize({ width: size, height: size, quality: 'best' });
    fs.writeFileSync(file, resized.toPNG());
    console.log('wrote', file, resized.getSize());
  }
  app.quit();
});
